use std::env
use std::fs
use std::process

fn emit(content: string, number: bool, counter: int) -> int {
    if !number {
        print(content)
        return counter
    }
    if content.len() == 0 {
        return counter
    }
    let mut c = counter
    for line in content.lines() {
        c += 1
        println("${c:>6}\t${line}")
    }
    c
}

fn main() {
    let args = env::args()
    let mut number = false
    let mut files: Vec<string> = []
    let mut k = 1
    while k < args.len() as int {
        let a = args[k as usize]
        if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
        k += 1
    }
    let mut counter = 0
    let mut status = 0
    if files.len() == 0 {
        match fs::read_to_string("/dev/stdin") {
            Ok(s) => { counter = emit(s, number, counter) }
            Err(e) => {}
        }
    } else {
        for f in files {
            if !fs::exists(f) {
                println("cat: ${f}: No such file")
                status = 1
            } else {
                match fs::read_to_string(f) {
                    Ok(s) => { counter = emit(s, number, counter) }
                    Err(e) => {
                        println("cat: ${f}: No such file")
                        status = 1
                    }
                }
            }
        }
    }
    if status != 0 {
        process::exit(1)
    }
}

